/**
 * @param {number[]} arr
 * @return {number[]}
 */
var sortByBits = function(arr) {
    arr.sort((a, b) => a - b);

    const map = {};

    for (const num of arr) {
        const bin = num.toString(2);
        let ones = bin.match(/1/g);
        ones = (ones && ones.length) || 0;
        map[ones] !== undefined ? map[ones].push(num) : (map[ones] = [num]);
    }

    return Object.keys(map)
        .map(key => map[key])
        .reduce((acc, res) => [ ...acc, ...res ], []);
};

/**
 * @param {number[]} arr
 * @return {number[]}
 */
var sortByBits = function(arr) {
    arr.sort((a, b) => a - b);

    const dp = Array.from({ length: 17 }, () => new Array());

    for (const num of arr) {
        const ones = num.toString(2).split('').filter(x => x === '1').length;
        dp[ones].push(num);
    }

    return dp.flat(1);
};
